int archive_read_support_zip_cleanup(struct archive_read *a) {
  struct zip *zip = (struct zip *)a->format->data;

  if (zip->zlib_used)
    inflateEnd(&(zip->strm_zlib));
  if (zip->lzma_used)
    lzma_end(&(zip->lzma_strm));
  if (zip->bzip2_used)
    BZ2_bzDecompressEnd(&(zip->bzip2_strm));

  while (zip->entries != NULL) {
    struct zip_entry *entry = zip->entries;
    zip->entries = entry->next;

    if (entry->is_unicode)
      free(entry->utf8_name);
    free(entry);
  }

  free(zip->central_dir);
  free(zip->filename);
  free(zip->comment);
  free(zip);
  a->format->data = NULL;

  return ARCHIVE_OK;
}

int
archive_read_support_zip_cleanup(struct archive_read *a)
{
	struct zip *zip;

	if (a == NULL)
		return (ARCHIVE_OK);

	zip = (struct zip *)(a->format->data);

	/* Release decompressing streams */
	if (zip->zstrm != NULL)
		inflateEnd(&zip->zstrm);
	if (zip->lzma_strm != NULL)
		lzma_stream_encoder_init(zip->lzma_strm, NULL);
	if (zip->bz2_strm != NULL)
		BZ2_bzDecompressEnd(zip->bz2_strm);

	/* Free buffers */
	free(zip->buffer);
	free(zip->local_extra);

	/* Free entries */
	while (zip->entries != NULL) {
		struct zip_entry *entry = zip->entries;
		zip->entries = entry->next;
		free(entry->extra);
		free(entry);
	}

	/* Free the main ZIP structure */
	free(zip);

	a->format->data = NULL;
	return (ARCHIVE_OK);
}

int
archive_read_support_zip_cleanup(struct archive_read *a)
{
	struct zip *zip = (struct zip *)(a->format->data);
	int ret = ARCHIVE_OK;

	if (zip == NULL)
		return (ARCHIVE_OK);

	/* Free zlib streams. */
	if (zip->z != NULL)
		inflateEnd(zip->z);
	if (zip->z_stream != NULL)
		inflateEnd(zip->z_stream);
	if (zip->z_opaque != NULL)
		inflateEnd(zip->z_opaque);

	/* Free BZ2 streams. */
	if (zip->bz2_stream != NULL)
		BZ2_bzDecompressEnd(zip->bz2_stream);

	/* Free LZMA streams. */
	if (zip->lzma_stream != NULL)
		lzma_end(zip->lzma_stream);

	/* Free entry resources. */
	while (zip->entries != NULL) {
		struct zip_entry *entry = zip->entries;
		zip->entries = zip->entries->next;
		free(entry->filename);
		free(entry->extra);
		free(entry);
	}

	/* Free main ZIP structure. */
	free(zip->central_directory);
	free(zip->local_file_headers);
	free(zip);

	a->format->data = NULL;

	return (ret);
}

int archive_read_free_zip(struct archive_read *a) {
  struct zip *zip = (struct zip *)(a->format_data);

  if (zip == NULL)
    return (ARCHIVE_OK);

  if (zip->zlib_stream != NULL)
    inflateEnd(zip->zlib_stream);
  if (zip->lzma_stream != NULL)
    lzma_end(zip->lzma_stream);
  if (zip->bz2_stream != NULL)
    BZ2_bzDecompressEnd(zip->bz2_stream);

  while (zip->entries != NULL) {
    struct zip_entry *entry = zip->entries;
    zip->entries = entry->next;

    if (entry->data != NULL)
      free(entry->data);
    free(entry);
  }

  if (zip->central_directory != NULL)
    free(zip->central_directory);
  if (zip->local_file_header != NULL)
    free(zip->local_file_header);
  if (zip->file_name != NULL)
    free(zip->file_name);
  if (zip->extra_field != NULL)
    free(zip->extra_field);

  free(zip);
  a->format_data = NULL;

  return (ARCHIVE_OK);
}

int
archive_read_free_zip(struct archive_read *a)
{
	struct zip *zip = (struct zip *)(a->format->data);

	if (zip == NULL)
		return (ARCHIVE_OK);

	/* Free decompression stream resources if allocated. */
	if (zip->zstream != NULL) {
		inflateEnd(&zip->zstream->zstream);
		free(zip->zstream);
		zip->zstream = NULL;
	}

	if (zip->bstream != NULL) {
		BZ2_bzDecompClose(zip->bstream);
		free(zip->bstream);
		zip->bstream = NULL;
	}

	if (zip->lstream != NULL) {
		lzma_end(zip->lstream);
		free(zip->lstream);
		zip->lstream = NULL;
	}

	/* Free each ZIP entry and its resources. */
	while (zip->entries != NULL) {
		struct zip_entry *entry = zip->entries;
		zip->entries = entry->next;

		if (entry->buffer != NULL)
			free(entry->buffer);
		if (entry->data != NULL)
			free(entry->data);
		free(entry);
	}

	/* Free the main ZIP structure. */
	free(zip);
	a->format->data = NULL;

	return (ARCHIVE_OK);
}
